    if(gameId===0){const won=s.tiles.every(x=>!x);return `<div class="dd-light-grid">${s.tiles.map((on,n)=>`<button data-depth="game-light" data-cell="${n}" class="${on?'lit':''}" aria-label="${t('Tile','格子')} ${n+1}: ${on?t('lit','亮'):t('dark','暗')}" ${won?'disabled':''}>${on?'✦':'·'}</button>`).join('')}</div><p class="dd-game-status" role="status">${won?t('All lights are out. You connected the garden!','所有灯已熄灭，花园连接完成！'):t('Turn every tile dark. A press also flips its four neighbours.','让所有格子熄灭，点击也会切换四个相邻格。')} · ${s.moves} ${t('presses','次点击')}</p>`;}
