    if(view==='play')return `<div class="d-play-page"><div class="d-row-heading"><div><small>LITTLE SIGNAL STUDIO</small><h1>${t(...games[gameId].slice(0,2))}</h1></div>${a('detail',t('← Game page','← 游戏详情'),'d-text-link',{id:gameId})}</div><p>${t(...gameRules[gameId][0])}</p><div class="dd-game-surface dd-game-${gameId}" id="dd-game-surface" tabindex="0" aria-label="${esc(t(...games[gameId].slice(0,2)))}">${gameBoard()}</div><div class="d-toolbar">${action('game-reset',t('Restart this game','重新开始此游戏'))}${D.btn('save',t('Add to your shelf','加入游戏架'))}${a('home',t('Other games','其他游戏'),'d-text-link')}</div><p class="d-fine">${t('Six original local mini-games. Progress is saved automatically.','六款原创本地小游戏，进度自动保存。')}</p></div>`;
